T.Translations("deDE", {
  ["off"] = "aus",
  ["too long"] = "zu lang",
  ["elsewhere"] = "anderswo",
  ["later"] = "später",
  ["in %s"] = "in %s",
  ["ready"] = "bereit",
  ["Message %d in chat reads"] = "Im Chat steht (Nachricht %d)",
  ["In chat it reads"] = "Im Chat steht",
  ["(nothing yet)"] = "(noch nichts)",
  ["%s matched none of your professions."] = "%s passt zu keinem deiner Berufe.",
  ["Press a key"] = "Taste drücken",
  ["Not set"] = "Nicht belegt",
  ["s"] = "s",
  ["every"] = "alle",
  ["Your messages"] = "Deine Nachrichten",
  ["Each message has its own button by your character, with its icon, its own countdown and its own time in seconds (%d at least): it lights up when that message is ready, and a click posts it. The post key posts the one that has waited longest. Click an icon here to pick another; until you do, a message shows the profession it links. Untick a message to keep it without posting it."] = "Jede Nachricht hat ihren eigenen Knopf bei deinem Charakter, mit ihrem Symbol, ihrem eigenen Countdown und ihrer eigenen Zeit in Sekunden (mindestens %d): Er leuchtet auf, wenn die Nachricht bereit ist, und ein Klick postet sie. Die Posttaste postet die, die am längsten wartet. Klick hier auf ein Symbol, um ein anderes zu wählen; bis dahin zeigt eine Nachricht den Beruf, den sie verlinkt. Nimm den Haken weg, um eine Nachricht zu behalten, ohne sie zu posten.",
  ["Add a message"] = "Nachricht hinzufügen",
  ["Put in a link:"] = "Link einfügen:",
  ["All professions"] = "Alle Berufe",
  ["(none of your professions has a link yet)"] = "(noch keiner deiner Berufe hat einen Link)",
  ["<Tailoring> becomes your Tailoring link when it is posted, <professions> all of them. Professions you gather with (and Fishing) have no link. The buttons put the link into the message you last clicked; shift-click an item or a recipe while a box has the cursor to put its link in."] = "<Schneiderei> wird beim Posten zu deinem Schneiderei-Link, <professions> zu allen. Sammelberufe (und Angeln) haben keinen Link. Die Knöpfe setzen den Link in die zuletzt angeklickte Nachricht; Umschalt-Klick auf einen Gegenstand oder ein Rezept, während ein Feld den Cursor hat, setzt dessen Link ein.",
  ["Post now"] = "Jetzt posten",
  ["The game sends a Trade chat message only when you click or press a key, so a message's button by your character lights up when it's ready and you post it with one click. Post now sends the one that has waited longest."] = "Das Spiel sendet eine Nachricht in den Handelschat nur bei einem Klick oder Tastendruck. Darum leuchtet der Knopf einer Nachricht bei deinem Charakter auf, wenn sie bereit ist, und du postest sie mit einem Klick. Jetzt posten sendet die, die am längsten wartet.",
  ["Pause on this character"] = "Auf diesem Charakter pausieren",
  ["Play a sound when it's time to post"] = "Ton abspielen, wenn es Zeit zum Posten ist",
  ["Say in chat when it's time to post"] = "Im Chat melden, wenn es Zeit zum Posten ist",
  ["Only show the button in cities"] = "Knöpfe nur in Städten zeigen",
  ["Lock the buttons in place"] = "Knöpfe festsetzen",
  ["Stack the buttons in a column"] = "Knöpfe untereinander anordnen",
  ["Post key"] = "Posttaste",
  ["%s did \"%s\"; while it posts, that comes back when you clear it here."] = "%s war mit „%s“ belegt; das kommt zurück, wenn du die Taste hier löschst.",
  ["Click, then press a key. Escape or right-click clears it."] = "Klick, dann eine Taste drücken. Escape oder Rechtsklick löscht sie.",
  ["Put the buttons back"] = "Knöpfe zurücksetzen",
  ["Your messages with your profession links in Trade chat, each again after its own time while you are in a city."] = "Deine Nachrichten mit deinen Berufslinks im Handelschat, jede wieder nach ihrer eigenen Zeit, solange du in einer Stadt bist.",
  ["Click to open the options."] = "Klicken, um die Optionen zu öffnen.",
  ["/crier opens the options. /crier post posts the message that has waited longest, /crier pause | resume, /crier status, /crier reset puts the buttons back, /crier feedback."] = "/crier öffnet die Optionen. /crier post postet die Nachricht, die am längsten wartet, /crier pause | resume, /crier status, /crier reset setzt die Knöpfe zurück, /crier feedback.",
})

